#!/usr/bin/env node
// Regenerates src/rest/openapi.ts from the server's OpenAPI document with
// openapi-typescript. Until the document exists (issue #45) src/rest/openapi.ts
// is hand-written in the same shape.
//
//   pnpm generate:types                      # ../../priv/static/openapi.json
//   pnpm generate:types path/or/url.json     # another file or a running server
//
// After generating, check that src/rest/types.ts still maps every public name
// to a schema of the generated file (`pnpm typecheck` fails otherwise).
import { existsSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const here = path.dirname(fileURLToPath(import.meta.url));
const source = process.argv[2] ?? process.env.OPENAPI_SPEC ?? path.resolve(here, "../../../priv/static/openapi.json");
const target = path.resolve(here, "../src/rest/openapi.ts");

const isUrl = /^https?:\/\//.test(source);
if (!isUrl && !existsSync(source)) {
  console.error(
    `OpenAPI document not found: ${source}\n` +
      "The server publishes it from issue #45 on (priv/static/openapi.json). Until then\n" +
      "src/rest/openapi.ts is hand-written; pass a path or URL to generate from elsewhere.",
  );
  process.exit(1);
}

const ast = await openapiTS(isUrl ? new URL(source) : pathToFileURL(path.resolve(source)), {
  exportType: false,
  alphabetize: true,
});
const banner =
  "/**\n * GENERATED by `pnpm generate:types` (openapi-typescript) from the Converger\n" +
  ` * OpenAPI document. Do not edit by hand.\n */\n\n`;
writeFileSync(target, banner + astToString(ast));
console.log(`wrote ${path.relative(process.cwd(), target)} from ${source}`);
